const ACCESS_MODES = ["read", "write"];
const DEFAULT_ACCESS = "read";
const DEFAULT_TIMEOUT_SEC = 600;
const DEFAULT_MAX_CHARS = 20000;
const MAX_TIMEOUT_SEC = 86400;

/** A positive integer from text, or undefined. */
